typedef Polyhedron::Halfedge_handle Halfedge_handle;
typedef Polyhedron::Vertex_handle Vertex_handle;
typedef Polyhedron::Facet_handle Facet_handle;
typedef Polyhedron::Halfedge_around_facet_circulator Halfedge_facet_circulator;

std::vector<Halfedge_handle> border_edges;
for (Polyhedron::Halfedge_iterator hit = poly.halfedges_begin(); hit != poly.halfedges_end(); ++hit) {
    if (hit->is_border()) {
        border_edges.push_back(hit);
    }
}

while (!border_edges.empty()) {
    Halfedge_handle start = border_edges.back();
    border_edges.pop_back();

    if (!start->is_border()) continue;

    std::vector<Vertex_handle> vertices;
    Halfedge_facet_circulator circ = poly.facet_circulator_of_border_edges(start);
    Halfedge_facet_circulator done(circ);
    do {
        vertices.push_back(circ->vertex());
        ++circ;
    } while (circ != done);

    if (vertices.size() < 3) continue;

    Vertex_handle v1 = vertices[0];
    Vertex_handle v2 = vertices[1];
    Vertex_handle v3 = vertices[2];

    if (vertices.size() == 3) {
        poly.add_facet_to_border(start, start->next()->next());
    } else {
        poly.fill_hole(start);
    }
}
